import os
import re
import hashlib
import tempfile
from pathlib import PurePosixPath
from flask import Flask, request, jsonify
import json

app = Flask(__name__)

BASE_UPLOAD_DIR = "/var/uploads/solidity_contracts"
ALLOWED_EXTENSIONS = {".sol", ".json", ".abi"}
MAX_FILE_SIZE = 1024 * 1024  # 1MB


class ContractMetadata:
    """Handles metadata extraction from Solidity contract uploads."""

    def __init__(self, project_id, compiler_version="0.8.19"):
        self.project_id = self._sanitize_project_id(project_id)
        self.compiler_version = compiler_version
        self._artifact_registry = {}

    def _sanitize_project_id(self, pid):
        """Ensure project ID is alphanumeric with hyphens only."""
        cleaned = re.sub(r'[^a-zA-Z0-9\-]', '', pid)
        if not cleaned or len(cleaned) > 64:
            raise ValueError("Invalid project ID")
        return cleaned

    def register_artifact(self, artifact_name, relative_path):
        """Register a compilation artifact with its relative path."""
        self._artifact_registry[artifact_name] = relative_path

    def get_artifact_path(self, artifact_name):
        return self._artifact_registry.get(artifact_name)


def normalize_contract_path(user_path, base_dir):
    """Normalize a user-supplied contract path relative to base directory.

    Uses a multi-stage normalization pipeline to handle various path formats
    from different operating systems and build tools.
    """
    # Stage 1: Strip null bytes and control characters
    cleaned = ''.join(c for c in user_path if ord(c) >= 32 and c != '\x00')

    # Stage 2: Normalize path separators to forward slash
    cleaned = cleaned.replace('\\', '/')

    # Stage 3: Collapse multiple slashes
    cleaned = re.sub(r'/+', '/', cleaned)

    # Stage 4: Resolve relative components using PurePosixPath
    # This handles '..' and '.' components safely
    resolved = PurePosixPath(cleaned)

    # Stage 5: Extract just the filename parts after normalization
    parts = resolved.parts

    # Stage 6: Rebuild path excluding any leading slash or drive
    safe_parts = []
    for part in parts:
        if part == '/' or part == '..':
            continue
        if part == '.':
            continue
        # Additional check: no part should try to escape
        if '..' in part:
            continue
        safe_parts.append(part)

    if not safe_parts:
        raise ValueError("Empty path after normalization")

    return os.path.join(base_dir, *safe_parts)


def validate_solidity_content(content_bytes):
    """Basic validation that content looks like a Solidity file."""
    try:
        text = content_bytes.decode('utf-8')
    except UnicodeDecodeError:
        return False
    # Check for common Solidity patterns
    if 'pragma solidity' in text or 'contract ' in text or 'interface ' in text:
        return True
    # Also allow ABI JSON files
    try:
        parsed = json.loads(text)
        if isinstance(parsed, list):
            return True
    except (json.JSONDecodeError, ValueError):
        pass
    return False


def compute_content_hash(data):
    """Compute SHA-256 hash for deduplication."""
    return hashlib.sha256(data).hexdigest()


@app.route('/api/v1/projects/<project_id>/upload', methods=['POST'])
def upload_contract(project_id):
    """Handle contract file upload for a specific project."""
    try:
        metadata = ContractMetadata(project_id)
    except ValueError as e:
        return jsonify({"error": str(e)}), 400

    if 'file' not in request.files:
        return jsonify({"error": "No file provided"}), 400

    uploaded_file = request.files['file']

    if not uploaded_file.filename:
        return jsonify({"error": "Empty filename"}), 400

    # Read content with size limit
    content = uploaded_file.read(MAX_FILE_SIZE + 1)
    if len(content) > MAX_FILE_SIZE:
        return jsonify({"error": "File too large"}), 413

    # Validate extension
    _, ext = os.path.splitext(uploaded_file.filename)
    if ext.lower() not in ALLOWED_EXTENSIONS:
        return jsonify({"error": f"Extension {ext} not allowed"}), 400

    # Validate content
    if ext.lower() == '.sol' and not validate_solidity_content(content):
        return jsonify({"error": "Invalid Solidity content"}), 400

    # Build the storage path
    # The user can specify a subdirectory structure via the 'path' form field
    # to organize contracts (e.g., "contracts/interfaces/IERC20.sol")
    user_specified_path = request.form.get('path', uploaded_file.filename)

    project_dir = os.path.join(BASE_UPLOAD_DIR, metadata.project_id)

    try:
        final_path = normalize_contract_path(user_specified_path, project_dir)
    except ValueError as e:
        return jsonify({"error": f"Invalid path: {e}"}), 400

    # Security check: ensure final path is within project directory
    # Use os.path.realpath to resolve any remaining symlinks
    canonical_base = os.path.realpath(project_dir)
    canonical_target = os.path.realpath(os.path.dirname(final_path))

    if not canonical_target.startswith(canonical_base):
        return jsonify({"error": "Path traversal detected"}), 403

    # Create directory structure and write file
    os.makedirs(os.path.dirname(final_path), exist_ok=True)

    content_hash = compute_content_hash(content)

    with open(final_path, 'wb') as f:
        f.write(content)

    metadata.register_artifact(uploaded_file.filename, user_specified_path)

    return jsonify({
        "status": "success",
        "path": user_specified_path,
        "hash": content_hash,
        "size": len(content)
    }), 201


@app.route('/api/v1/projects/<project_id>/contracts', methods=['GET'])
def list_contracts(project_id):
    """List all uploaded contracts for a project."""
    try:
        metadata = ContractMetadata(project_id)
    except ValueError:
        return jsonify({"error": "Invalid project ID"}), 400

    project_dir = os.path.join(BASE_UPLOAD_DIR, metadata.project_id)

    if not os.path.isdir(project_dir):
        return jsonify({"contracts": []}), 200

    contracts = []
    for root, dirs, files in os.walk(project_dir):
        for fname in files:
            full_path = os.path.join(root, fname)
            rel_path = os.path.relpath(full_path, project_dir)
            contracts.append({
                "path": rel_path,
                "size": os.path.getsize(full_path)
            })

    return jsonify({"contracts": contracts}), 200


if __name__ == '__main__':
    os.makedirs(BASE_UPLOAD_DIR, exist_ok=True)
    app.run(host='127.0.0.1', port=5000, debug=False)
